/* ------------------------------------------------------------------ */
/* Regions — the umbrella tier above individual cities                */
/* ------------------------------------------------------------------ */

/**
 * Region-level landing pages ("American VPS Hosting", "European Game Server
 * Hosting") sit one level above the city matrix above. They exist to catch
 * broader, higher-volume searches from people who don't specify a city
 * ("american vps hosting", "hosting in europe") without duplicating any
 * single city's copy — a region page aggregates and links to its real,
 * already-live city pages rather than inventing new individual-city claims.
 *
 * Only regions with more than one existing `LocationDef` city are included:
 * a region built from a single city would just be a thin reskin of that
 * city's own page, which is exactly the doorway-page pattern this system is
 * designed to avoid. That's why there's no standalone Canada, Middle East or
 * South America region page today — Toronto, Dubai and São Paulo are each
 * the only `LocationDef` in their region, so their own city pages already
 * are the regional page.
 *
 * Honesty note: same discipline as `LocationDef.presence` above, but scoped
 * to the region as a whole. `"market"` regions (USA, Europe) contain zero
 * real Nxeon datacenters — copy is audience/market-first and the FAQ says so
 * plainly. Asia-Pacific is the one exception worth calling out explicitly:
 * Nxeon's actual, real, only production datacenter (Singapore) sits inside
 * this region, so its page can truthfully say the region contains real
 * Nxeon infrastructure — while still being careful never to imply that
 * infrastructure exists in, say, Mumbai or Seoul.
 */
export type RegionDef = {
  /** URL slug fragment, e.g. "usa". */
  slug: string;
  /** Full display name for prose, e.g. "the United States". */
  name: string;
  /** Short, title-case label for meta titles, e.g. "United States". */
  shortLabel: string;
  /** Adjective for the audience, e.g. "American". */
  audience: string;
  /** Longer regional phrase for prose, analogous to LocationDef.regionLong. */
  regionLong: string;
  /** One factual sentence about the region's connectivity/context. */
  blurb: string;
  /** Which existing LocationDef slugs make up this region (real, live pages only). */
  locationSlugs: string[];
  /** Whether the region contains a real Nxeon datacenter city (today: only Asia-Pacific, via Singapore). */
  presence: "datacenter" | "market";
};

export const REGIONS: RegionDef[] = [
  {
    slug: "usa",
    name: "the United States",
    shortLabel: "United States",
    audience: "American",
    regionLong: "the United States, coast to coast",
    blurb: "From New York and Miami on the East Coast to Los Angeles on the West, with Dallas and Chicago anchoring the middle of the country, these five cities sit on the US's biggest interconnection campuses — Equinix and CoreSite in New York, the NAP of the Americas in Miami, the trans-Pacific gateways in LA, the Infomart and Equinix DA campus in Dallas, and 350 East Cermak in Chicago.",
    locationSlugs: ["new-york", "los-angeles", "dallas", "miami", "chicago"],
    presence: "market",
  },
  {
    slug: "europe",
    name: "Europe",
    shortLabel: "Europe",
    audience: "European",
    regionLong: "the United Kingdom and the European mainland",
    blurb: "London, Frankfurt, Amsterdam and Paris host four of the continent's largest internet exchanges — LINX, DE-CIX, AMS-IX and France-IX — putting this page's four constituent cities at the actual centre of Europe's peering fabric, not just on a map.",
    locationSlugs: ["london", "frankfurt", "amsterdam", "paris"],
    presence: "market",
  },
  {
    slug: "asia-pacific",
    name: "Asia-Pacific",
    shortLabel: "Asia-Pacific",
    audience: "Asia-Pacific",
    regionLong: "Southeast Asia, South Asia, East Asia and Oceania",
    blurb: "Nxeon's production datacenter is physically located in Singapore — inside this region — with market-facing pages extending out to Sydney, Tokyo, Mumbai, Hong Kong and Seoul, each a major interconnection hub in its own part of Asia-Pacific.",
    locationSlugs: ["singapore", "sydney", "tokyo", "mumbai", "hong-kong", "seoul"],
    presence: "datacenter",
  },
];

export type RegionCombo = { region: RegionDef; service: ServiceDef; slug: string };

export const REGION_COMBOS: RegionCombo[] = REGIONS.flatMap((region) =>
  SERVICES.map((service) => ({
    region,
    service,
    slug: `${region.slug}-${service.urlPart}`,
  })),
);

const REGION_COMBO_BY_SLUG = new Map(REGION_COMBOS.map((c) => [c.slug, c]));

export function findRegionCombo(slug: string): RegionCombo | undefined {
  return REGION_COMBO_BY_SLUG.get(slug);
}

/** All region-tier slugs (for generateStaticParams + the sitemap), parallel to LANDING_SLUGS. */
export const REGION_LANDING_SLUGS: string[] = REGION_COMBOS.map((c) => c.slug);

function citiesOf(reg: RegionDef): LocationDef[] {
  return reg.locationSlugs.map((s) => LOCATIONS_BY_SLUG.get(s)!).filter(Boolean);
}

/** Honest answer to "where are the servers?" scoped to the region as a whole. */
function regionServerLocationFaq(reg: RegionDef, cityPhrase: string): { q: string; a: string } {
  if (reg.presence === "datacenter") {
    return {
      q: `Does Nxeon actually have a datacenter in ${reg.name}?`,
      a: `Yes — Nxeon's production datacenter is physically located in Singapore, inside ${reg.name}. This page is aimed at the broader ${reg.audience} market though, not Singapore specifically: if Singapore itself is your target, the dedicated Singapore VPS Hosting page has datacenter-specific detail. For the other ${reg.audience} markets this page covers — ${cityPhrase} — you'll deploy to the nearest available region at checkout, and each city has its own page with an honest answer on where its traffic is actually served from.`,
    };
  }
  return {
    q: `Are the servers physically located in ${reg.name}?`,
    a: `This page is built for the ${reg.audience} market broadly — the audience across ${reg.regionLong} — not a claim of on-site infrastructure. Nxeon's production platform runs from a Singapore datacenter today, with regional build-out underway, so at checkout you deploy to the nearest available region. If a specific city matters to your workload, the individual city pages below (${cityPhrase}) each answer this question for that city specifically, and our team can confirm the lowest-latency option before you order.`,
  };
}

const REGION_TRADING_SUMMARY: Record<string, string> = {
  usa: "the NYSE and Nasdaq in New York, CME Group — the world's largest derivatives exchange — in Chicago, and a fast-growing base of prop-trading and fintech firms in Dallas and Miami",
  europe: "the London Stock Exchange and the largest cluster of FX interbank desks anywhere, Frankfurt's Deutsche Börse and Eurex, and Euronext's exchanges in both Amsterdam and Paris",
  "asia-pacific": "the Singapore Exchange, the Tokyo Stock Exchange, the Hong Kong Stock Exchange, South Korea's KRX in Seoul, and India's NSE and BSE in Mumbai",
};

function regionTradingHub(reg: RegionDef): string {
  return REGION_TRADING_SUMMARY[reg.slug] ?? `an active base of ${reg.audience.toLowerCase()} trading and fintech firms`;
}

/**
 * Internal links for a region page: the constituent city pages for the SAME
 * service (real, already-live URLs — this is the whole point of the region
 * tier), the sibling services for this same region, this service's hub page,
 * and pricing.
 */
function regionRelatedLinks(comboR: RegionCombo): { label: string; href: string }[] {
  const { region: reg, service: svc } = comboR;
  const cityLinks = citiesOf(reg).map((loc) => ({
    label: `${loc.city} ${svc.label}`,
    href: `/${loc.slug}-${svc.urlPart}`,
  }));
  const siblingServices = SERVICES.filter((s) => s.key !== svc.key).map((s) => ({
    label: `${reg.shortLabel} ${s.label}`,
    href: `/${reg.slug}-${s.urlPart}`,
  }));
  return [...cityLinks, ...siblingServices, svc.hub, { label: "Pricing", href: "/pricing" }];
}

/**
 * Build the full, unique landing content for one (region × service) combo.
 * Structurally mirrors `buildLanding` above (same BuiltLanding shape so the
 * route can render either through the same `UseCaseLanding` component), but
 * every paragraph is written at the region's aggregate level — it names and
 * links the real constituent cities rather than picking one city's story,
 * and explicitly frames itself as the broader page above them.
 */
export function buildRegionLanding(comboR: RegionCombo, plans: LandingPlan[]): BuiltLanding {
  const { region: reg, service: svc } = comboR;
  const from = fromLabel(plans);
  const cities = citiesOf(reg);
  const cityNames = cities.map((c) => c.city);
  const cityPhrase = listPhrase(cityNames);
  const cityPhrase3 = listPhrase(cityNames.slice(0, 3));
  const cityLinks = cities.map((loc) => ({ label: loc.city, href: `/${loc.slug}-${svc.urlPart}` }));
  const locationFaq = regionServerLocationFaq(reg, cityPhrase);

  const byService: Record<ServiceKey, Omit<BuiltLanding, "breadcrumbName">> = {
    vps: {
      metaTitle: `${reg.audience} VPS Hosting — Cloud VPS Across ${reg.shortLabel}`,
      metaDescription: `${reg.audience} VPS hosting covering ${cityPhrase}. Full-root NVMe cloud servers with a dedicated IPv4, DDoS protection and one-click deploys, from ${from}/mo. Pick the nearest hub for ${reg.regionLong}.`,
      ogTitle: `${reg.audience} VPS Hosting — one platform, ${cities.length} hubs across ${reg.shortLabel}`,
      ogDescription: `Full-root NVMe VPS aimed at ${reg.regionLong}, with dedicated pages for ${cityPhrase}. From ${from}/mo.`,
      content: {
        eyebrow: `${reg.audience} VPS hosting`,
        title: `A cloud VPS built for`,
        highlight: reg.name,
        sub: `One full-root NVMe VPS platform, aimed at every major market across ${reg.regionLong} — ${cityPhrase} — with a dedicated IPv4, DDoS protection and one-click deploys, from ${from}/mo.`,
        intro: [
          `Not every ${reg.audience.toLowerCase()} search is for one city. Plenty of people looking for "${reg.audience.toLowerCase()} VPS hosting" haven't picked New York over Chicago yet — they just know their users, team or business are somewhere across ${reg.name}. This page is for that search: an overview of how Nxeon covers ${reg.name}, with a direct link to the sharpest-matching city page for each of ${cityPhrase}.`,
          `${reg.blurb}`,
          `The VPS itself is identical everywhere: enterprise NVMe on a self-healing ZFS mirror, a dedicated IPv4, always-on DDoS protection with a managed firewall, daily backups and snapshots, and one-click OS or app images live in about 47 seconds. What changes city to city is which hub gets you the shortest route — pick a city page below for market-specific detail, or deploy from here and choose your nearest region at checkout.`,
        ],
        whyTitle: `Why Nxeon across ${reg.name}`,
        why: [
          { title: `${cities.length} markets, one platform`, body: `The same full-root NVMe VPS, priced and supported identically whether you're closest to ${cityPhrase3}.` },
          { title: "Full root, your stack", body: "SSH in and run anything — Docker, databases, Node, control panels. No locked-down shared box, anywhere in the region." },
          { title: "Enterprise NVMe on ZFS", body: "Fast, consistent storage on enterprise NVMe over a self-healing ZFS mirror at every hub." },
          { title: "Dedicated IPv4 + DDoS", body: "Your own IPv4 and always-on DDoS protection with a managed firewall come with every plan, in every city." },
          { title: "Pick your nearest hub", body: `Deploy toward whichever of ${cityPhrase} is closest to your users — no separate account or price tier per city.` },
          { title: "One-click resize", body: "Add vCPU, RAM or disk without a rebuild as your traffic grows, wherever in the region you're serving from." },
        ],
        steps: [
          { title: "Create your account free", body: "No card required. Open the deploy wizard in seconds." },
          { title: "Pick your nearest hub", body: `Choose the region closest to your ${reg.audience.toLowerCase()} audience — see the city pages below if you want market-specific detail first.` },
          { title: "Deploy & point your domain", body: "Your VPS is live in ~47 seconds with a dedicated IP. Aim your DNS at it and issue SSL." },
          { title: "Tune and scale", body: "With full root you own the stack; one-click resize grows the box as demand does." },
        ],
        specNote: `Starter (2 GB) or Standard (4 GB) covers most sites and APIs anywhere in ${reg.name}; step up to Pro (8 GB) for busier apps. Every plan ships with a dedicated IP — resize any time.`,
        faq: [
          locationFaq,
